def ticket_for_line(store, line: StatementLine) -> Optional[Ticket]:
    if line.account_ref in store.tickets:
        return store.tickets[line.account_ref]

    normalized_ref = line.account_ref.lower().replace(" ", "").replace("-", "")
    for ticket_id, ticket in store.tickets.items():
        if ticket_id.lower().replace(" ", "").replace("-", "") == normalized_ref:
            return ticket
    return None

